import openpyxl
from pathlib import Path
rows=[]
for p in sorted(Path('/workspace/inspect/exomes').glob('*.xlsx')):
 try:
  wb=openpyxl.load_workbook(p, read_only=True, data_only=True); ws=wb.active
  n=max(ws.max_row-2,0)
  rows.append((p.name,p.stat().st_size,n,ws.max_row))
 except Exception as e: rows.append((p.name,None,'ERR',str(e)))
for r in rows[:100]: print(r)
print('total data',sum(r[2] for r in rows if isinstance(r[2],int)))
PY"

